# -----------------------------
# Sync UOM Table
# -----------------------------

default_uom = doc.stock_uom or "Nos"

doc.set("uoms", [])

# base uom mandatory
doc.append("uoms", {
    "uom": default_uom,
    "conversion_factor": 1
})

seen_uoms = {default_uom}

for row in (doc.custom_retail_packing_detail or []):

    if row.uom and row.uom not in seen_uoms:

        doc.append("uoms", {
            "uom": row.uom,
            "conversion_factor": row.conversion_factor or 1
        })
        seen_uoms.add(row.uom)

# -----------------------------
# Sync Barcode Table
# -----------------------------

doc.set("barcodes", [])
seen_barcodes = set()

# quick/default barcode from the Item form
if doc.custom_barcode:
    barcode = doc.custom_barcode.strip()
    if barcode:
        doc.append("barcodes", {
            "barcode": barcode,
            "uom": default_uom
        })
        seen_barcodes.add(barcode)

# advanced multi-UOM barcodes from Retail Packing Detail
for row in (doc.custom_retail_packing_detail or []):

    if row.barcode:
        barcode = row.barcode.strip()
        if barcode and barcode not in seen_barcodes:

            doc.append("barcodes", {
                "barcode": barcode,
                "uom": row.uom or default_uom
            })
            seen_barcodes.add(barcode)
